70		clusterSecrets, err := db.listSecretsByType(common.LabelValueSecretTypeCluster)
71		if err != nil {
72			return nil, err
73		}
74		clusterList := appv1.ClusterList{
75			Items: make([]appv1.Cluster, 0),
76		}
77		settings, err := db.settingsMgr.GetSettings()
78		if err != nil {
79			return nil, err
80		}
81		inClusterEnabled := settings.InClusterEnabled
82		hasInClusterCredentials := false
83		for _, clusterSecret := range clusterSecrets {
84			cluster, err := SecretToCluster(clusterSecret)
85			if err != nil {
86				log.Errorf("could not unmarshal cluster secret %s", clusterSecret.Name)
87				continue
88			}
89			if cluster.Server == appv1.KubernetesInternalAPIServerAddr {
90				if inClusterEnabled {
91					hasInClusterCredentials = true
92					clusterList.Items = append(clusterList.Items, *cluster)
93				}
94			} else {
95				clusterList.Items = append(clusterList.Items, *cluster)
96			}
97		}
98		if inClusterEnabled && !hasInClusterCredentials {
99			clusterList.Items = append(clusterList.Items, *db.getLocalCluster())
100		}
101		return &clusterList, nil
102	}
