293	func (db *db) GetClusterServersByName(_ context.Context, name string) ([]string, error) {
294		informer, err := db.settingsMgr.GetClusterInformer()
295		if err != nil {
296			return nil, fmt.Errorf("failed to get cluster informer: %w", err)
297		}
298		servers, err := informer.GetClusterServersByName(name)
299		if err != nil {
300			return nil, err
301		}
302	
303		// attempt to short circuit if the in-cluster name is not involved
304		if name != appv1.KubernetesInClusterName && !slices.Contains(servers, appv1.KubernetesInternalAPIServerAddr) {
305			return servers, nil
306		}
307	
308		inClusterEnabled, err := db.settingsMgr.IsInClusterEnabled()
309		if err != nil {
310			return nil, fmt.Errorf(errCheckingInClusterEnabled, "GetClusterServersByName", err)
311		}
312	
313		// Handle local cluster special case
314		if len(servers) == 0 && name == appv1.KubernetesInClusterName && inClusterEnabled {
315			return []string{appv1.KubernetesInternalAPIServerAddr}, nil
316		}
317	
318		// Filter out disabled in-cluster
319		if !inClusterEnabled {
320			filtered := make([]string, 0, len(servers))
321			for _, s := range servers {
322				if s != appv1.KubernetesInternalAPIServerAddr {
323					filtered = append(filtered, s)
324				}
325			}
326			return filtered, nil
327		}
328	
329		return servers, nil
330	}
